WITH claimed AS ( UPDATE email_attachments SET upload_claimed_at = NOW() WHERE id IN ( SELECT a.id FROM email_attachments a JOIN email_messages m ON a.message_id = m.id LEFT JOIN email_attachments_sfs eas ON eas.attachment_id = a.id WHERE m.link_id = $2 AND m.provider_id = $1 AND a.reference_url IS NULL AND (a.mime_type LIKE 'image/%' OR a.mime_type LIKE 'video/%') AND eas.attachment_id IS NULL AND a.upload_claimed_at IS NULL ) RETURNING id ) SELECT a.id AS attachment_db_id, m.provider_id as email_provider_id, a.provider_attachment_id as provider_attachment_id, a.filename as filename, a.mime_type as mime_type, m.internal_date_ts as internal_date_ts, m.id as message_db_id, m.thread_id as thread_db_id, from_contact.email_address as sender_email, m.subject as subject FROM email_attachments a JOIN email_messages m ON a.message_id = m.id -- A draft can have no sender; every claimed row must come back or its -- claim is never released. LEFT JOIN email_contacts from_contact ON m.from_contact_id = from_contact.id WHERE a.id IN (SELECT id FROM claimed) ORDER BY a.id
